import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;
import javax.servlet.annotation.*;
import java.util.logging.*;

@WebServlet("/api/users")
public class UserSearchServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(UserSearchServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String searchTerm = req.getParameter("q");
        String department = req.getParameter("dept");
        String sortCol = req.getParameter("sort");
        String limit = req.getParameter("limit");

        if (searchTerm == null || searchTerm.isEmpty()) {
            resp.sendError(400, "Missing search parameter");
            return;
        }

        // Basic length check - not a security control, just UX
        if (searchTerm.length() > 200) {
            resp.sendError(400, "Search term too long");
            return;
        }

        // Sanitize sort column against allowlist
        List<String> allowedSorts = Arrays.asList("name", "email", "created_at", "department");
        if (sortCol == null || !allowedSorts.contains(sortCol)) {
            sortCol = "name";
        }

        // Validate limit is numeric
        int limitVal = 50;
        try {
            if (limit != null) limitVal = Math.min(Integer.parseInt(limit), 200);
        } catch (NumberFormatException e) {
            limitVal = 50;
        }

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - department filter uses parameterized approach
            // but search uses string concat for LIKE wildcard support
            StringBuilder query = new StringBuilder();
            query.append("SELECT id, name, email, department, created_at FROM users WHERE ");

            if (department != null && !department.isEmpty()) {
                // This looks safe but department is also concatenated
                query.append("department = '").append(department.replace("'", "''")).append("' AND ");
            }

            // Vulnerable: searchTerm directly concatenated
            query.append("(name LIKE '%" + searchTerm + "%' OR email LIKE '%" + searchTerm + "%') ");
            query.append("ORDER BY ").append(sortCol).append(" LIMIT ").append(limitVal);

            log.info("Executing search query for term: " + searchTerm.substring(0, Math.min(20, searchTerm.length())));

            ResultSet rs = stmt.executeQuery(query.toString());
            resp.setContentType("application/json");
            var writer = resp.getWriter();
            writer.write("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) writer.write(",\n");
                writer.write(String.format(
                    "{\"id\":%d,\"name\":\"%s\",\"email\":\"%s\",\"dept\":\"%s\"}",
                    rs.getInt("id"),
                    rs.getString("name").replace("\"", "\\\""),
                    rs.getString("email").replace("\"", "\\\""),
                    rs.getString("department").replace("\"", "\\\"")
                ));
                first = false;
            }
            writer.write("\n]");
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException e) {}
            try { if (conn != null) conn.close(); } catch (SQLException e) {}
        }
    }
}
